            printf("Voltage: %.4f V\n", voltage);
        } else {
            fprintf(stderr, "Failed to read ADC value.\n");
        }
        usleep(100000); // 0.1 seconds
    }

    printf("\nExiting...\n");
    close(fd);
    return 0;
}

