#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device absent or permissions?).\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        for (int duty = 0; duty <= PWM_RANGE && running; duty += 10) {
            if (gpioPWM(PWM_PIN, duty) != 0) {
                fprintf(stderr, "Error: gpioPWM failed on GPIO %d.\n", PWM_PIN);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("GPIO %d: duty cycle = %d\n", PWM_PIN, duty);
            fflush(stdout);
            time_sleep(0.5);
        }
        for (int duty = PWM_RANGE; duty >= 0 && running; duty -= 10) {
            if (gpioPWM(PWM_PIN, duty) != 0) {
                fprintf(stderr, "Error: gpioPWM failed on GPIO %d.\n", PWM_PIN);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("GPIO %d: duty cycle = %d\n", PWM_PIN, duty);
            fflush(stdout);
            time_sleep(0.5);
        }
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define CHIP_NAME   "gpiochip0"
#define TIMEOUT_US  30000   /* 30 ms timeout for a 5 m round trip */
#define SPEED_CM_S  34300.0
#define SLEEP_S     60

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

static long long now_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static long long elapsed_us(long long start)
{
    return now_us() - start;
}

static int wait_for_level(struct gpiod_line *line, int target, long long timeout_us)
{
    long long deadline = now_us() + timeout_us;
    int val;
    while ((val = gpiod_line_get_value(line)) < 0) {
        if (now_us() > deadline) {
            return -1;
        }
        usleep(10);
    }
    return (val == target) ? 0 : -1;
}

static int measure_distance(struct gpiod_line *trig, struct gpiod_line *echo)
{
    long long t0, t1;

    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        return -1;
    }
    usleep(5);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        return -1;
    }

    /* Wait for echo rising edge (timeout) */
    if (wait_for_level(echo, 1, TIMEOUT_US) < 0) {
        return -1;
    }
    t0 = now_us();

    /* Wait for echo falling edge (timeout) */
    if (wait_for_level(echo, 0, TIMEOUT_US) < 0) {
        return -1;
    }
    t1 = now_us();

    long long elapsed = t1 - t0;
    double distance = (double)elapsed * SPEED_CM_S / 2000000.0;
    return (distance > 2.0 && distance < 400.0) ? (int)(distance * 100.0) : -1;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line(trigger)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trigger)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        int dist = measure_distance(trig, echo);
        if (dist < 0) {
            fprintf(stderr, "Error: HC-SR04 not responding or out of range.\n");
        } else {
            printf("Distance: %.2f cm\n", dist / 100.0);
        }
        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SLEEP_S && running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) {
        gpiod_line_release(trig);
    }
    if (echo) {
        gpiod_line_release(echo);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x28
#define CONFIG_REG     0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE    3.3f
#define SAMPLE_PERIOD  5

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "i2c_write16: write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read16: write reg failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read16: read failed: %s\n", strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int16_t read_ads1115(int fd) {
    uint16_t config = 0x8483; /* AIN0 single-ended, 4.096V, single-shot, 128SPS */
    if (i2c_write16(fd, CONFIG_REG, config) < 0) return -1;
    usleep(10000); /* 10 ms conversion time */

    uint16_t raw;
    if (i2c_read16(fd, CONVERSION_REG, &raw) < 0) return -1;
    return (int16_t)raw;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", ADS1115_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    printf("ADS1115 sampling at 0x%02X every %d s. Ctrl+C to exit.\n", ADS1115_ADDR, SAMPLE_PERIOD);

    while (running) {
        int16_t raw = read_ads1115(fd);
        if (raw < 0) {
            fprintf(stderr, "ADS1115 read error; continuing.\n");
        } else {
            float voltage = (raw / 32767.0f) * REF_VOLTAGE;
            printf("Voltage: %.3f V\n", voltage);
        }
        sleep(SAMPLE_PERIOD);
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return 0;
}

