#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 3.3f
#define I2C_DEVICE "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int fd = -1;
    int16_t raw;
    float voltage;
    uint8_t config[3];
    uint8_t reg;
    uint8_t buf[2];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Config: AIN0 single-ended, 4.096V, single-shot, 128 SPS, start conversion */
    config[0] = CONFIG_REG;
    config[1] = 0xC1; /* MUX=100 (AIN0), PGA=001 (4.096V), MODE=1 (single-shot) */
    config[2] = 0x83; /* DR=100 (128 SPS), COMP_QUE=11 (disable comparator) */

    if (write(fd, config, 3) != 3) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Wait for conversion to complete (~8ms at 128 SPS) */
    usleep(10000);

    reg = CONVERSION_REG;
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error selecting conversion register: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading conversion register: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    raw = (int16_t)((buf[0] << 8) | buf[1]);
    voltage = (raw * REF_VOLTAGE) / 32768.0f;

    printf("Voltage: %.4f V\n", voltage);

    close(fd);
    return EXIT_SUCCESS;
}

