        if (gpiod_line_request_output(lines[i], "output-cycle", 0) < 0) {
            fprintf(stderr, "Failed to request line %u as output\n", pins[i]);
            goto cleanup;
        }
    }

    for (int cycle = 0; cycle < 256 && running; cycle++) {
        for (i = 0; i < NUM_PINS; i++) {
            int val = (cycle >> i) & 1;
            if (gpiod_line_set_value(lines[i], val) < 0) {
                perror("gpiod_line_set_value");
                goto cleanup;
