#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 8

static struct gpiod_line *line = NULL;
static struct gpiod_chip *chip = NULL;

static void cleanup_and_exit(int signum) {
    (void)signum;
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main(void) {
    int ret;
    int val;

    /* Open GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    /* Request output, initial value 0 */
    ret = gpiod_line_request_output(line, "output-test", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    /* Read and report current value */
    val = gpiod_line_get_value(line);
    if (val < 0) {
        perror("gpiod_line_get_value");
        cleanup_and_exit(0);
    }
    printf("Current value on GPIO %d: %d\n", GPIO_LINE, val);

    /* Set up signal handler for clean exit */
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    /* Keep the program alive until a signal is received */
    while (1) {
        sleep(1);
    }

    return 0;
}

