#include <gpiod.h>

#define CONSUMER "output_control"
#define NUM_PINS 4
static const unsigned int pins[NUM_PINS] = {8, 9, 10, 11};

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int values[NUM_PINS] = {0, 0, 0, 0};
    int i;

    for (i = 0; i < NUM_PINS; i++)
        lines[i] = NULL;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request line %u as output\n", pins[i]);
            goto cleanup;
        }
    }

    while (running) {
        for (i = 0; i < NUM_PINS; i++) {
            int v = !values[i];
            if (gpiod_line_set_value(lines[i], v) < 0) {
                fprintf(stderr, "Failed to set line %u\n", pins[i]);
                goto cleanup;
            }
            values[i] = v;
        }
        for (i = 0; i < NUM_PINS; i++)
            printf("Pin %u: %d\n", pins[i], values[i]);
        fflush(stdout);
        usleep(100000);
    }

cleanup:
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip)
        gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

