#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define CONSUMER    "hcsr04"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    running = 0;
}

static long long elapsed_ms(struct timespec *start, struct timespec *end)
{
    return (long long)(end->tv_sec - start->tv_sec) * 1000LL +
           (end->tv_nsec - start->tv_nsec) / 1000000LL;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line(trigger)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(trigger)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    while (running) {
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value(trigger high)");
            goto cleanup;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trigger low)");
            goto cleanup;
        }

        struct timespec t_start, t_end;
        int val;
        int timeout = 0;

        while (running) {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value(echo)");
                goto cleanup;
            }
            if (val == 1) {
                clock_gettime(CLOCK_MONOTONIC, &t_start);
                break;
            }
            if (timeout++ > 100000) {
                fprintf(stderr, "Error: HC-SR04 trigger timeout (device absent?)\n");
                goto cleanup;
            }
            usleep(1);
        }

        if (!running) break;

        timeout = 0;
        while (running) {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value(echo)");
                goto cleanup;
            }
            if (val == 0) {
                clock_gettime(CLOCK_MONOTONIC, &t_end);
                break;
            }
            if (timeout++ > 100000) {
                fprintf(stderr, "Error: HC-SR04 echo timeout (stuck high?)\n");
                goto cleanup;
            }
            usleep(1);
        }

        if (!running) break;

        long long dur = elapsed_ms(&t_start, &t_end);
        if (dur < 2 || dur > 500) {
            fprintf(stderr, "Warning: measurement out of range (%lld ms)\n", dur);
        } else {
            double dist = (dur * 1.0) * 170.0;
            printf("Distance: %.2f cm\n", dist);
