#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define DHT11_PIN 4
#define MAX_RETRIES 5
#define MAX_TIMEOUT_US 200000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_us(unsigned int us) {
    struct timespec ts = {
        .tv_sec = us / 1000000U,
        .tv_nsec = (long)(us % 1000000U) * 1000L
    };
    nanosleep(&ts, NULL);
}

static int wait_level(struct gpiod_line *line, int level, unsigned int timeout_us) {
    unsigned int elapsed = 0;
    while (running) {
        if (gpiod_line_get_value(line) == level) return 0;
        sleep_us(1);
        elapsed += 1;
        if (elapsed >= timeout_us) return -1;
    }
    return -1;
}

static int read_dht11(struct gpiod_line *line, float *temperature, float *humidity) {
    uint8_t data[5] = {0};
    int i;

    if (gpiod_line_request_output(line, "dht11", 1) < 0) {
        fprintf(stderr, "Failed to request line as output\n");
        return -1;
    }
    gpiod_line_set_value(line, 1);
    sleep_us(500000);
    gpiod_line_set_value(line, 0);
    sleep_us(20000);
    gpiod_line_set_value(line, 1);
    if (gpiod_line_request_input(line, "dht11") < 0) {
        fprintf(stderr, "Failed to request line as input\n");
        return -1;
    }

    if (wait_level(line, 0, MAX_TIMEOUT_US) < 0) {
        fprintf(stderr, "DHT11 response timeout (no low)\n");
        return -1;
    }
    if (wait_level(line, 1, MAX_TIMEOUT_US) < 0) {
        fprintf(stderr, "DHT11 response timeout (no high)\n");
        return -1;
    }
    if (wait_level(line, 0, MAX_TIMEOUT_US) < 0) {
        fprintf(stderr, "DHT11 response timeout (no start bit)\n");
        return -1;
    }

    for (i = 0; i < 40; i++) {
        if (wait_level(line, 1, MAX_TIMEOUT_US) < 0) {
            fprintf(stderr, "DHT11 timeout waiting for bit %d\n", i);
            return -1;
        }
        uint32_t start = (uint32_t)clock();
        if (wait_level(line, 0, MAX_TIMEOUT_US) < 0) {
            fprintf(stderr, "DHT11 timeout waiting for end of bit %d\n", i);
            return -1;
        }
        uint32_t end = (uint32_t)clock();
        uint32_t duration = end - start;
        if (duration > 50) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "DHT11 checksum error\n");
        return -1;
    }

    *humidity = (float)((data[0] << 8) | data[1]) / 10.0f;
    *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
    if (data[2] & 0x80) *temperature = -*temperature;

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float temperature, humidity;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT11_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (!running) break;
        if (read_dht11(line, &temperature, &humidity) == 0) {
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
            ret = EXIT_SUCCESS;
            break;
        }
        fprintf(stderr, "DHT11 read failed (attempt %d/%d)\n", attempt + 1, MAX_RETRIES);
        sleep_us(100000);
    }

cleanup:
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

