#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_2  2
#define PWM_PIN_3  3
#define PWM_PIN_18 18
#define PWM_RANGE  1000
#define PWM_FREQ   1000
#define LOOP_US   150000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device absent or permissions?).\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_2, PI_OUTPUT) < 0 ||
        gpioSetMode(PWM_PIN_3, PI_OUTPUT) < 0 ||
        gpioSetMode(PWM_PIN_18, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) < 0 ||
        gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) < 0 ||
        gpioSetPWMrange(PWM_PIN_18, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(PWM_PIN_18, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install signal handlers.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int s2 = (rand() % 100) + 1;
        int s3 = (rand() % 100) + 1;
        int s18 = (rand() % 100) + 1;

        if (gpioPWM(PWM_PIN_2, s2) < 0 ||
            gpioPWM(PWM_PIN_3, s3) < 0 ||
            gpioPWM(PWM_PIN_18, s18) < 0) {
            fprintf(stderr, "Error: gpioPWM failed.\n");
            break;
        }

        printf("GPIO 2: %d, GPIO 3: %d, GPIO 18: %d\n", s2, s3, s18);
        fflush(stdout);

        usleep(LOOP_US);
    }

    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_18, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

