#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 2
#define CYCLE_COUNT 3
#define DELAY_MS 100

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "output-cycle", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    for (int i = 0; i < CYCLE_COUNT && keep_running; i++) {
        int val = i % 2;
        if (gpiod_line_set_value(line, val) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }
        printf("Cycle %d: GPIO %d set to %d\n", i + 1, GPIO_LINE, val);
        usleep(DELAY_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 4
#define PWM_PIN_2 12
#define PWM_PIN_3 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int duty1 = gpioGetPWMdutycycle(PWM_PIN_1);
        int duty2 = gpioGetPWMdutycycle(PWM_PIN_2);
        int duty3 = gpioGetPWMdutycycle(PWM_PIN_3);

        if (duty1 < 0 || duty2 < 0 || duty3 < 0) {
            fprintf(stderr, "Failed to read PWM duty cycle\n");
            break;
        }

        printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n",
               PWM_PIN_1, duty1, PWM_PIN_2, duty2, PWM_PIN_3, duty3);
        fflush(stdout);

        gpioDelay(1000000);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

