#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <time.h>

#define W1_GPIO_4   "/sys/bus/w1/devices/28-00000b4b4b4b/gpio4"
#define W1_GPIO_17  "/sys/bus/w1/devices/28-00000b4b4b4b/gpio17"
#define W1_GPIO_18  "/sys/bus/w1/devices/28-00000b4b4b4b/gpio18"
#define W1_GPIO_DIR "/sys/bus/w1/devices/28-00000b4b4b4b/gpio"
#define W1_DEVICES  "/sys/bus/w1/devices/w1_bus_master1/w1_master_slaves"
#define READ_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_file(const char *path, char *buf, size_t len) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) return -1;
    ssize_t n = read(fd, buf, len - 1);
    close(fd);
    if (n < 0) return -1;
    buf[n] = '\0';
    return 0;
}

static int write_file(const char *path, const char *val) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    if (write(fd, val, strlen(val)) < 0) { close(fd); return -1; }
    close(fd);
    return 0;
}

static int w1_read_temp(const char *base, float *temp) {
    char path[256];
    char buf[256];

    snprintf(path, sizeof(path), "%s/w1_slave", base);
    if (read_file(path, buf, sizeof(buf)) < 0) return -1;

    char *t = strstr(buf, "t=");
    if (!t) return -1;

    long raw = strtol(t + 2, NULL, 10);
    if (raw == 0) return -1;

    *temp = raw / 1000.0f;
    return 0;
}

static int w1_init(void) {
    char buf[256];
    if (read_file(W1_DEVICES, buf, sizeof(buf)) < 0) return -1;
    if (strstr(buf, "28-00000b4b4b4b") == NULL) {
        fprintf(stderr, "DS18B20 not found on 1-Wire bus.\n");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (w1_init() < 0) return EXIT_FAILURE;

    while (running) {
        float t;
        if (w1_read_temp(W1_GPIO_DIR, &t) == 0) {
            printf("GPIO 4: %.2f C\n", t);
        } else {
            fprintf(stderr, "GPIO 4 read failed: %s\n", strerror(errno));
        }

        if (running) sleep(READ_INTERVAL);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HTU21D_ADDR 0x40
#define I2C_DEV "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int read_temperature_humidity(int fd, float *temp, float *hum) {
    uint8_t msb, lsb, checksum;

    if (i2c_write_reg8(fd, 0xE3, 0x00) < 0) return -1;
    usleep(50000);
    if (i2c_read_reg8(fd, 0x00, &msb) < 0) return -1;
    if (i2c_read_reg8(fd, 0x01, &lsb) < 0) return -1;
    if (i2c_read_reg8(fd, 0x02, &checksum) < 0) return -1;

    uint16_t raw_t = ((uint16_t)msb << 8) | lsb;
    if (checksum != ((raw_t >> 8) ^ raw_t) & 0xFF) return -1;

    if (i2c_write_reg8(fd, 0xE5, 0x00) < 0) return -1;
    usleep(50000);
    if (i2c_read_reg8(fd, 0x00, &msb) < 0) return -1;
    if (i2c_read_reg8(fd, 0x01, &lsb) < 0) return -1;
    if (i2c_read_reg8(fd, 0x02, &checksum) < 0) return -1;

    uint16_t raw_h = ((uint16_t)msb << 8) | lsb;
    if (checksum != ((raw_h >> 8) ^ raw_h) & 0xFF) return -1;

    *temp = -46.85 + 175.72 * ((float)raw_t / 65536.0);
    *hum = -6.0 + 125.0 * ((float)raw_h / 65536.0);
    if (*hum < 0.0) *hum = 0.0;
    if (*hum > 100.0) *hum = 100.0;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", HTU21D_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    while (running) {
        float temp, hum;
        if (read_temperature_humidity(fd, &temp, &hum) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
            fflush(stdout);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }
        sleep(60);
    }

    close(fd);
    return 0;
}

