#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02
#define TCS34725_ATIME 0x01
#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { (uint8_t)(reg | TCS34725_COMMAND_BIT), val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    uint8_t cmd = (uint8_t)(reg | TCS34725_COMMAND_BIT);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int tcs34725_init(int fd) {
    uint8_t id;
    if (i2c_read_block(fd, TCS34725_ID, &id, 1) < 0) return -1;
    if (id != 0x44 && id != 0x10) {
        fprintf(stderr, "Unexpected TCS34725 ID: 0x%02X (expected 0x44 or 0x10)\n", id);
        return -1;
    }
    if (i2c_write(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0) return -1;
    usleep(3000);
    if (i2c_write(fd, TCS34725_ATIME, 0xFF) < 0) return -1;
    if (i2c_write(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) return -1;
    return 0;
}

static int tcs34725_read(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c) {
    uint8_t buf[8];
    if (i2c_read_block(fd, TCS34725_CDATA, buf, 8) < 0) return -1;
    *c = (uint16_t)((buf[1] << 8) | buf[0]);
    *r = (uint16_t)((buf[3] << 8) | buf[2]);
    *g = (uint16_t)((buf[5] << 8) | buf[4]);
    *b = (uint16_t)((buf[7] << 8) | buf[6]);
    return 0;
}

int main(void) {
    int fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TCS34725_ADDRESS, strerror(errno));
        goto cleanup;
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        goto cleanup;
    }

    while (running) {
        uint16_t r, g, b, c;
        if (tcs34725_read(fd, &r, &g, &b, &c) < 0) {
            fprintf(stderr, "Failed to read TCS34725 data.\n");
            goto cleanup;
        }
        printf("C: %5u  R: %5u  G: %5u  B: %5u\n", c, r, g, b);
        fflush(stdout);
        usleep(200000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        i2c_write(fd, TCS34725_ENABLE, 0x00);
        close(fd);
    }
    return rc;
}

