#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SSD1306_I2C_ADDR 0x3C
#define SSD1306_WIDTH 128
#define SSD1306_HEIGHT 64
#define SSD1306_PAGES (SSD1306_HEIGHT / 8)
#define SSD1306_BUFFER_SIZE (SSD1306_WIDTH * SSD1306_PAGES)

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write(int fd, uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int ssd1306_command(int fd, uint8_t cmd) {
    uint8_t buf[2] = {0x00, cmd};
    return i2c_write(fd, buf, 2);
}

static int ssd1306_command2(int fd, uint8_t cmd1, uint8_t cmd2) {
    uint8_t buf[3] = {0x00, cmd1, cmd2};
    return i2c_write(fd, buf, 3);
}

static int ssd1306_init(int fd) {
    if (ssd1306_command(fd, 0xAE) < 0) return -1;
    if (ssd1306_command(fd, 0xD5) < 0) return -1;
    if (ssd1306_command(fd, 0x80) < 0) return -1;
    if (ssd1306_command(fd, 0xA8) < 0) return -1;
    if (ssd1306_command(fd, 0x3F) < 0) return -1;
    if (ssd1306_command(fd, 0xD3) < 0) return -1;
    if (ssd1306_command(fd, 0x00) < 0) return -1;
    if (ssd1306_command(fd, 0x40) < 0) return -1;
    if (ssd1306_command(fd, 0x8D) < 0) return -1;
    if (ssd1306_command(fd, 0x14) < 0) return -1;
    if (ssd1306_command(fd, 0x20) < 0) return -1;
    if (ssd1306_command(fd, 0x00) < 0) return -1;
    if (ssd1306_command(fd, 0xA1) < 0) return -1;
    if (ssd1306_command(fd, 0xC8) < 0) return -1;
    if (ssd1306_command(fd, 0xDA) < 0) return -1;
    if (ssd1306_command(fd, 0x12) < 0) return -1;
    if (ssd1306_command(fd, 0x81) < 0) return -1;
    if (ssd1306_command(fd, 0xCF) < 0) return -1;
    if (ssd1306_command(fd, 0xD9) < 0) return -1;
    if (ssd1306_command(fd, 0xF1) < 0) return -1;
    if (ssd1306_command(fd, 0xDB) < 0) return -1;
    if (ssd1306_command(fd, 0x40) < 0) return -1;
    if (ssd1306_command(fd, 0xA4) < 0) return -1;
    if (ssd1306_command(fd, 0xA6) < 0) return -1;
    if (ssd1306_command(fd, 0xAF) < 0) return -1;
    return 0;
}

static int ssd1306_clear(int fd) {
    uint8_t buf[1 + SSD1306_BUFFER_SIZE];
    buf[0] = 0x40;
    memset(buf + 1, 0x00, SSD1306_BUFFER_SIZE);
    return i2c_write(fd, buf, 1 + SSD1306_BUFFER_SIZE);
}

static int ssd1306_display(int fd, uint8_t *buffer) {
    uint8_t buf[1 + SSD1306_BUFFER_SIZE];
    buf[0] = 0x40;
    memcpy(buf + 1, buffer, SSD1306_BUFFER_SIZE);
    return i2c_write(fd, buf, 1 + SSD1306_BUFFER_SIZE);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SSD1306_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SSD1306_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (ssd1306_init(fd) < 0) {
        fprintf(stderr, "SSD1306 initialization failed\n");
        close(fd);
        return 1;
    }

    if (ssd1306_clear(fd) < 0) {
        fprintf(stderr, "SSD1306 clear failed\n");
        close(fd);
        return 1;
    }

    uint8_t buffer[SSD1306_BUFFER_SIZE];
    memset(buffer, 0, sizeof(buffer));

    while (running) {
        int val = (int)(rand() % 100);
        int x = (int)(rand() % SSD1306_WIDTH);
        int y = (int)(rand() % SSD1306_PAGES);

        if (x < 0 || x >= SSD1306_WIDTH || y < 0 || y >= SSD1306_PAGES) {
            fprintf(stderr, "Invalid coordinates: x=%d, y=%d\n", x, y);
            continue;
        }

        int byte_index = x + (y * SSD1306_WIDTH);
        buffer[byte_index] = (uint8_t)val;

        if (ssd1306_display(fd, buffer) < 0) {
            fprintf(stderr, "SSD1306 display failed\n");
            break;
        }

        usleep(100000);
    }

    if (ssd1306_clear(fd) < 0) {
        fprintf(stderr, "SSD1306 clear on exit failed\n");
    }

    close(fd);
    return 0;
}

