#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 8
#define PWM_PIN_2 9
#define PWM_PIN_3 11
#define PWM_PIN_4 18

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) < 0 ||
        gpioSetMode(PWM_PIN_2, PI_OUTPUT) < 0 ||
        gpioSetMode(PWM_PIN_3, PI_OUTPUT) < 0 ||
        gpioSetMode(PWM_PIN_4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int s1 = gpioPWM(PWM_PIN_1, 128);
        int s2 = gpioPWM(PWM_PIN_2, 192);
        int s3 = gpioPWM(PWM_PIN_3, 64);
        int s4 = gpioPWM(PWM_PIN_4, 255);

        if (s1 < 0 || s2 < 0 || s3 < 0 || s4 < 0) {
            fprintf(stderr, "PWM write failed\n");
            break;
        }

        printf("PWM: %d %d %d %d\n", s1, s2, s3, s4);
        fflush(stdout);

        gpioDelay(1000000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    23
#define SENSOR_PIN  24

#define CHIP_NAME   "gpiochip0"
#define CONSUMER    "hcsr04"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    running = 0;
}

static long long now_us(void)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *sensor = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    sensor = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!trig || !echo || !sensor) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, CONSUMER, 0) < 0) {
        perror("request trigger as output");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        perror("request echo as input");
        goto cleanup;
    }
    if (gpiod_line_request_input(sensor, CONSUMER) < 0) {
        perror("request sensor as input");
        goto cleanup;
    }

    while (running) {
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("set trigger high");
            goto cleanup;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("set trigger low");
            goto cleanup;
        }

        long long start = now_us();
        int val;
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("read echo");
                goto cleanup;
            }
            if (now_us() - start > 100000) {
                fprintf(stderr, "Timeout waiting for echo start\n");
                goto cleanup;
            }
        } while (val == 0);

        long long echo_start = now_us();
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("read echo");
                goto cleanup;
            }
            if (now_us() - echo_start > 100000) {
                fprintf(stderr, "Timeout waiting for echo end\n");
                goto cleanup;
            }
        } while (val == 1);

        long long echo_end = now_us();
        long long pulse_us = echo_end - echo_start;

        int state = gpiod_line_get_value(sensor);
        if (state < 0) {
            perror("read sensor");
            goto cleanup;
        }

        printf("State: %d, Pulse: %lld us\n", state, pulse_us);
        fflush(stdout);

        usleep(200000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (sensor) gpiod_line_release(sensor);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN 18
#define NUM_PIXELS 1
#define DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device absent or permissions?).\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (gpioWrite(LED_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to write HIGH to GPIO %d.\n", LED_PIN);
            break;
        }
        gpioDelay(DELAY_US);
        if (!running) break;
        if (gpioWrite(LED_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to write LOW to GPIO %d.\n", LED_PIN);
            break;
        }
        gpioDelay(DELAY_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

