#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_PINS 8
static const unsigned int pins[NUM_PINS] = {1, 4, 5, 6, 21, 22, 23, 24};

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int vals[NUM_PINS];
    int i, ret;

    for (i = 0; i < NUM_PINS; i++)
        lines[i] = NULL;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
        ret = gpiod_line_request_output(lines[i], "output-test", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %u as output: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
        vals[i] = gpiod_line_get_value(lines[i]);
        if (vals[i] < 0) {
            fprintf(stderr, "Failed to read initial value of line %u: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (i = 0; i < NUM_PINS; i++)
        printf("GPIO %u: %d\n", pins[i], vals[i]);
    printf("---\n");

    if (!running)
        goto cleanup;

    for (i = 0; i < NUM_PINS; i++) {
        ret = gpiod_line_set_value(lines[i], !vals[i]);
        if (ret < 0) {
            fprintf(stderr, "Failed to toggle line %u: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
        vals[i] = !vals[i];
    }

    for (i = 0; i < NUM_PINS; i++)
        printf("GPIO %u: %d\n", pins[i], vals[i]);
    printf("---\n");

    if (!running)
        goto cleanup;

    for (i = 0; i < NUM_PINS; i++) {
        ret = gpiod_line_set_value(lines[i], 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line %u low: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("All outputs set to LOW\n");
    ret = EXIT_SUCCESS;
    goto cleanup;

cleanup:
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <sys/mman.h>

#define DEVICE_NAME "/dev/video0"
#define CAPTURE_WIDTH 640
#define CAPTURE_HEIGHT 480
#define CAPTURE_FORMAT V4L2_PIX_FMT_JPEG
#define CAPTURE_JPEG_QUALITY 85
#define CAPTURE_INTERVAL_MS 50

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;
    FILE *fp = NULL;
    char filename[64];
    struct timespec ts = {0, CAPTURE_INTERVAL_MS * 1000000L};

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        goto cleanup;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = CAPTURE_WIDTH;
    fmt.fmt.pix.height = CAPTURE_HEIGHT;
    fmt.fmt.pix.pixelformat = CAPTURE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        goto cleanup;
    }

    if (fmt.fmt.pix.pixelformat != CAPTURE_FORMAT) {
        fprintf(stderr, "Device does not support JPEG format\n");
        goto cleanup;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    void *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        munmap(buffer, buf.length);
        goto cleanup;
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        munmap(buffer, buf.length);
        goto cleanup;
    }

    while (running) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            if (errno == EAGAIN) {
                continue;
            }
            fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
            break;
        }

        snprintf(filename, sizeof(filename), "image_%ld.jpg", time(NULL));
        fp = fopen(filename, "wb");
        if (fp == NULL) {
            fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
            xioctl(fd, VIDIOC_QBUF, &buf);
            break;
        }

        size_t written = fwrite(buffer, 1, buf.bytesused, fp);
        if (written != buf.bytesused) {
            fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
            fclose(fp);
            fp = NULL;
            xioctl(fd, VIDIOC_QBUF, &buf);
            break;
        }

        if (fclose(fp) != 0) {
            fprintf(stderr, "Error closing file: %s\n", strerror(errno));
            fp = NULL;
            xioctl(fd, VIDIOC_QBUF, &buf);
            break;
        }
        fp = NULL;

        printf("Captured image: %s (%ld bytes)\n", filename, written);

        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
            break;
        }

        nanosleep(&ts, NULL);
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    xioctl(fd, VIDIOC_STREAMOFF, &type);

    if (buffer != MAP_FAILED) {
        munmap(buffer, buf.length);
    }

cleanup:
    if (fd != -1) {
        close(fd);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define BME280_I2C_ADDR 0x76
#define I2C_DEVICE "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_reg16_le(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)buf[1] << 8 | buf[0];
    return 0;
}

static int i2c_read_reg24_le(int fd, uint8_t reg, uint32_t *val) {
    uint8_t buf[3];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 3) != 3) return -1;
    *val = (uint32_t)buf[2] << 16 | (uint32_t)buf[1] << 8 | buf[0];
    return 0;
}

static int bme280_init(int fd) {
    uint8_t chip_id;
    if (i2c_read_reg8(fd, 0xD0, &chip_id) < 0) {
        fprintf(stderr, "Error: Failed to read chip ID register: %s\n", strerror(errno));
        return -1;
    }
    if (chip_id != 0x60) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x60)\n", chip_id);
        return -1;
    }
    return 0;
}

static int bme280_read(int fd, float *temp, float *hum, float *press) {
    uint8_t data[8];
    if (write(fd, (uint8_t[]){0xF7, 0xF8, 0xF9, 0xFA}, 4) != 4) return -1;
    if (read(fd, data, 8) != 8) return -1;
    uint32_t raw_p = (uint32_t)data[0] << 12 | (uint32_t)data[1] << 4 | data[2] >> 4;
    uint32_t raw_t = (uint32_t)data[3] << 12 | (uint32_t)data[4] << 4 | data[5] >> 4;
    uint16_t raw_h = (uint16_t)data[6] << 8 | data[7];
    *press = (float)raw_p / 256.0f;
    *temp = (float)raw_t / 100.0f;
    *hum = (float)raw_h / 1024.0f;
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address 0x%02X: %s\n", BME280_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (bme280_init(fd) < 0) {
        close(fd);
        return 1;
    }

    while (running) {
        float temp, hum, press;
        if (bme280_read(fd, &temp, &hum, &press) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%, Pressure: %.2f hPa\n", temp, hum, press);
        } else {
            fprintf(stderr, "Error: Failed to read BME280 data: %s\n", strerror(errno));
        }
        sleep(5);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define ADS1115_CONFIG_OS_BEGIN (1 << 15)
#define ADS1115_CONFIG_MUX_AIN0_GND (0x04 << 12)
#define ADS1115_CONFIG_PGA_4_096V (0x01 << 9)
#define ADS1115_CONFIG_MODE_SINGLE (0x01 << 8)
#define ADS1115_CONFIG_DR_128SPS (0x00 << 5)
#define ADS1115_CONFIG_CQUE_NONE (0x03 << 0)

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (val >> 8) & 0xFF;
    buf[2] = val & 0xFF;
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "i2c_write16: write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read16: write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read16: read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int read_ads1115(int fd, int16_t *raw) {
    uint16_t config = ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0_GND |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;

    if (i2c_write16(fd, ADS1115_REG_CONFIG, config) < 0) {
        return -1;
    }

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    usleep(10000);

    uint16_t cfg;
    for (int i = 0; i < 10; i++) {
        if (i2c_read16(fd, ADS1115_REG_CONFIG, &cfg) < 0) {
            return -1;
        }
        if (cfg & ADS1115_CONFIG_OS_BEGIN) {
            break;
        }
        usleep(1000);
    }

    if (!(cfg & ADS1115_CONFIG_OS_BEGIN)) {
        fprintf(stderr, "ADS1115 conversion timeout\n");
        return -1;
    }

    uint16_t val;
    if (i2c_read16(fd, ADS1115_REG_CONVERSION, &val) < 0) {
        return -1;
    }

    *raw = (int16_t)val;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", ADS1115_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    printf("ADS1115 initialized at 0x%02X on %s\n", ADS1115_ADDR, I2C_BUS);

    while (running) {
        int16_t raw;
        if (read_ads1115(fd, &raw) < 0) {
            fprintf(stderr, "Failed to read ADS1115\n");
            break;
        }
        printf("Raw: %d\n", raw);
        usleep(200000);
    }

    close(fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

