#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define LCD_ADDR 0x27
#define LCD_WIDTH 20

#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_LINE_1 0x80
#define LCD_LINE_2 0xC0
#define LCD_BACKLIGHT 0x08
#define ENABLE 0x04

static int i2c_fd = -1;
static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

void lcd_write_nibble(uint8_t nibble) {
    uint8_t data[4];
    data[0] = LCD_BACKLIGHT | (nibble & 0xF0);
    data[1] = LCD_BACKLIGHT | (nibble << 4) & 0xF0;
    data[2] = LCD_BACKLIGHT | (nibble << 4) & 0xF0 | ENABLE;
    data[3] = LCD_BACKLIGHT | (nibble << 4) & 0xF0;

    if (write(i2c_fd, data, 4) != 4) {
        fprintf(stderr, "Error writing to I2C: %s\n", strerror(errno));
    }
    usleep(1000);
}

void lcd_send_byte(uint8_t bits, uint8_t mode) {
    lcd_write_nibble(bits & 0xF0);
    lcd_write_nibble((bits << 4) & 0xF0);
}

void lcd_command(uint8_t cmd) {
    lcd_send_byte(cmd, LCD_CMD);
    usleep(2000);
}

void lcd_data(uint8_t data) {
    lcd_send_byte(data, LCD_CHR);
    usleep(200);
}

void lcd_string(const char *s) {
    while (*s) {
        lcd_data((uint8_t)*s++);
    }
}

void lcd_clear(void) {
    lcd_command(0x01);
    usleep(2000);
}

void lcd_init(void) {
    usleep(50000);
    lcd_write_nibble(0x30);
    usleep(5000);
    lcd_write_nibble(0x30);
    usleep(150);
    lcd_write_nibble(0x30);
    usleep(150);
    lcd_write_nibble(0x20);
    usleep(150);
    lcd_command(0x28);
    lcd_command(0x08);
    lcd_command(0x01);
    usleep(2000);
    lcd_command(0x06);
    lcd_command(0x0C);
}

void lcd_set_cursor(uint8_t col, uint8_t row) {
    uint8_t addr = (row == 0) ? 0x80 + col : 0xC0 + col;
    lcd_command(addr);
}

void cleanup(void) {
    if (i2c_fd >= 0) {
        lcd_clear();
        lcd_set_cursor(0, 0);
        lcd_string("Goodbye!");
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LCD_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    lcd_init();

    while (keep_running) {
        char line1[LCD_WIDTH + 1];
        char line2[LCD_WIDTH + 1];

        snprintf(line1, sizeof(line1), "Temperature: 25.5C");
        snprintf(line2, sizeof(line2), "Humidity: 60.2%%");

        lcd_clear();
        lcd_set_cursor(0, 0);
        lcd_string(line1);
        lcd_set_cursor(0, 1);
        lcd_string(line2);

        sleep(10);
    }

    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) < 0) {
        return -1;
    }
    usleep(100000);
    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t xh, xl, yh, yl, zh, zl;
    if (i2c_read_reg(fd, ACCEL_XOUT_H, &xh) < 0) return -1;
    if (i2c_read_reg(fd, ACCEL_XOUT_L, &xl) < 0) return -1;
    if (i2c_read_reg(fd, ACCEL_YOUT_H, &yh) < 0) return -1;
    if (i2c_read_reg(fd, ACCEL_YOUT_L, &yl) < 0) return -1;
    if (i2c_read_reg(fd, ACCEL_ZOUT_H, &zh) < 0) return -1;
    if (i2c_read_reg(fd, ACCEL_ZOUT_L, &zl) < 0) return -1;
    *x = (int16_t)((xh << 8) | xl);
    *y = (int16_t)((yh << 8) | yl);
    *z = (int16_t)((zh << 8) | zl);
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        goto cleanup;
    }

    if (init_mpu6050(fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU6050\n");
        goto cleanup;
    }

    for (int i = 0; i < 100 && running; i++) {
        int16_t x, y, z;
        if (read_accel(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            goto cleanup;
        }
        printf("Reading %d: X=%d, Y=%d, Z=%d\n", i + 1, x, y, z);
        usleep(100000);
    }

    if (running) {
        printf("100 readings completed successfully.\n");
        ret = EXIT_SUCCESS;
    }

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

