#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <paho-mqtt-c/mqtt_client.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_CLIENT_ID "rpi_sensor_1"
#define MQTT_TOPIC "sensor/data"
#define MQTT_QOS 1
#define MQTT_TIMEOUT_MS 1000
#define PUBLISH_INTERVAL_US 10000
#define MAX_PAYLOAD_LEN 256

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) return -1;
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", timeinfo) == 0) return -1;
    return 0;
}

static int get_sensor_data(float *temperature, float *humidity) {
    FILE *fp;
    char line[256];
    char filename[] = "/sys/bus/w1/devices/28-00000xxxxxxx/w1_slave";
    char *token;
    char *endptr;
    long raw_temp, raw_hum;

    fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening sensor file");
        return -1;
    }

    if (fgets(line, sizeof(line), fp) == NULL) {
        perror("Error reading temperature line");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    token = strstr(line, "t=");
    if (token == NULL) {
        fprintf(stderr, "Error: Temperature data not found in file\n");
        return -1;
    }

    raw_temp = strtol(token + 2, &endptr, 10);
    if (*endptr != '\0' && *endptr != '\n') {
        fprintf(stderr, "Error: Temperature data truncated or invalid\n");
        return -1;
    }

    if (fgets(line, sizeof(line), fp) == NULL) {
        perror("Error reading humidity line");
        return -1;
    }

    token = strstr(line, "h=");
    if (token == NULL) {
        fprintf(stderr, "Error: Humidity data not found in file\n");
        return -1;
    }

    raw_hum = strtol(token + 2, &endptr, 10);
    if (*endptr != '\0' && *endptr != '\n') {
        fprintf(stderr, "Error: Humidity data truncated or invalid\n");
        return -1;
    }

    *temperature = (float)raw_temp / 1000.0;
    *humidity = (float)raw_hum / 1000.0;

    return 0;
}

static int validate_sensor_data(float temperature, float humidity) {
    if (temperature < -50.0 || temperature > 100.0) {
        fprintf(stderr, "Error: Temperature out of range: %.2f\n", temperature);
        return -1;
    }
    if (humidity < 0.0 || humidity > 100.0) {
        fprintf(stderr, "Error: Humidity out of range: %.2f\n", humidity);
        return -1;
    }
    return 0;
}

static int publish_sensor_data(MQTTClient *client, const char *topic, float temperature, float humidity) {
    char payload[MAX_PAYLOAD_LEN];
    char timestamp[32];
    int payload_len;

    if (get_timestamp(timestamp, sizeof(timestamp)) != 0) {
        fprintf(stderr, "Error: Failed to get timestamp\n");
        return -1;
    }

    payload_len = snprintf(payload, sizeof(payload), "{\"timestamp\": \"%s\", \"temperature\": %.2f, \"humidity\": %.2f}", timestamp, temperature, humidity);
    if (payload_len < 0 || payload_len >= (int)sizeof(payload)) {
        fprintf(stderr, "Error: Payload formatting failed\n");
        return -1;
    }

    if (MQTTClient_publish(*client, topic, MQTT_QOS, payload, MQTT_TIMEOUT_MS) != MQTTCLIENT_SUCCESS) {
