int main() {
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    float temperature, humidity;
    int rc;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: Failed to set SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: Failed to set SIGTERM handler");
        return 1;
    }

    if (MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: Failed to create MQTT client\n");
        return 1;
    }

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: Failed to connect to MQTT broker, return code %d\n", rc);
        MQTTClient_destroy(&client);
        return 1;
    }

    printf("Connected to MQTT broker. Publishing sensor data...\n");

    while (running) {
        if (get_sensor_data(&temperature, &humidity) != 0) {
            fprintf(stderr, "Error: Failed to get sensor data. Retrying...\n");
            usleep(PUBLISH_INTERVAL_US);
            continue;
        }

        if (validate_sensor_data(temperature, humidity) != 0) {
            fprintf(stderr, "Error: Sensor data validation failed. Retrying...\n");
            usleep(PUBLISH_INTERVAL_US);
            continue;
        }

        if (publish_sensor_data(&client, MQTT_TOPIC, temperature, humidity) != 0) {
            fprintf(stderr, "Error: Failed to publish sensor data. Retrying...\n");
        }

        usleep(PUBLISH_INTERVAL_US);
    }

    printf("\nDisconnecting from MQTT broker...\n");
    MQTTClient_disconnect(client, MQTT_TIMEOUT_MS);
    MQTTClient_destroy(&client);
    printf("Exiting.\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 23
#define CONSUMER "output_control"

static volatile sig_atomic_t keep_running = 1;

static void int_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value 0 */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop: toggle the line every 5 seconds */
    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        val = val ? 0 : 1;
        ret = gpiod_line_set_value(line, val);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE, val);
        fflush(stdout);

        /* Sleep 5 seconds, but wake early if interrupted */
        for (int i = 0; i < 5 && keep_running; i++) {
            sleep(1);
        }
    }

    /* Clean up: release the line and close the chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    22
#define NUM_PINS    2

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static int measure(struct gpiod_line *trig, struct gpiod_line *echo,
                    long long *out_us) {
    if (gpiod_line_set_value(trig, 0) < 0) return -1;
    usleep(2);
    if (gpiod_line_set_value(trig, 1) < 0) return -1;
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) return -1;

    long long deadline = now_us() + 100000LL;
    while (gpiod_line_get_value(echo) == 0) {
        if (now_us() > deadline) return -1;
    }
    long long start = now_us();

    deadline = now_us() + 100000LL;
    while (gpiod_line_get_value(echo) == 1) {
        if (now_us() > deadline) return -1;
    }
    long long end = now_us();

    *out_us = end - start;
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    struct gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trig, "hc-sr04", 0) < 0) {
        perror("gpiod_line_request_output (trigger)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(echo, "hc-sr04") < 0) {
        perror("gpiod_line_request_input (echo)");
        gpiod_line_release(trig);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        long long dur;
        if (measure(trig, echo, &dur) == 0) {
            if (dur >= 2 && dur <= 40000) {
                double dist_cm = (double)dur * 0.0343 / 2.0;
                printf("Distance: %.2f cm\n", dist_cm);
            } else {
                fprintf(stderr, "Warning: reading out of range (%lld us)\n", dur);
            }
        } else {
            fprintf(stderr, "Warning: sensor not responding or timeout\n");
        }
        usleep(100000);
    }

    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

