#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <paho-mqtt-c/mqtt_client.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_CLIENT_ID "rpi_sensor_1"
#define MQTT_TOPIC "sensor/data"
#define MQTT_QOS 0
#define MQTT_TIMEOUT_MS 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(float *temperature, float *humidity) {
    FILE *fp;
    char line[256];
    char *token;

    fp = fopen("/sys/bus/iio/devices/iio:device0/in_voltage0_input", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1;
    }

    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    token = strtok(line, "\n");
    if (token == NULL) {
        fprintf(stderr, "Error parsing temperature\n");
        return -1;
    }
    *temperature = atof(token);

    fp = fopen("/sys/bus/iio/devices/iio:device0/in_voltage1_input", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening humidity file: %s\n", strerror(errno));
        return -1;
    }

    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading humidity: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    token = strtok(line, "\n");
    if (token == NULL) {
        fprintf(stderr, "Error parsing humidity\n");
        return -1;
    }
    *humidity = atof(token);

    return 0;
}

int main() {
    int rc;
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    MQTTClient_message message;
    MQTTClient_deliveryToken token;
    float temperature, humidity;
    char payload[256];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (read_sensor_data(&temperature, &humidity) != 0) {
        fprintf(stderr, "Sensor read failed. Exiting.\n");
        return 1;
    }

    rc = MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client: %s\n", MQTTClient_strerror(rc));
        return 1;
    }

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        return 1;
    }

    snprintf(payload, sizeof(payload), "{\"temperature\": %.2f, \"humidity\": %.2f}", temperature, humidity);

    message.payload = payload;
    message.payloadlen = (int)strlen(payload);
    message.qos = MQTT_QOS;
    message.retained = 0;

    rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &message, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message: %s\n", MQTTClient_strerror(rc));
        MQTTClient_disconnect(client, MQTT_TIMEOUT_MS);
        MQTTClient_destroy(&client);
        return 1;
    }

    rc = MQTTClient_waitForCompletion(client, token, MQTT_TIMEOUT_MS);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to wait for message delivery: %s\n", MQTTClient_strerror(rc));
    } else {
        printf("Message published successfully.\n");
    }

    MQTTClient_disconnect(client, MQTT_TIMEOUT_MS);
    MQTTClient_destroy(&client);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define DELAY_SEC 5

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device absent or permissions?).\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        for (int duty = 0; duty <= PWM_RANGE && running; duty += 100) {
            if (gpioPWM(PWM_PIN, duty) != 0) {
                fprintf(stderr, "Error: gpioPWM failed on GPIO %d.\n", PWM_PIN);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("GPIO %d: PWM duty cycle = %d\n", PWM_PIN, duty);
            fflush(stdout);
            sleep(1);
        }
        for (int duty = PWM_RANGE; duty >= 0 && running; duty -= 100) {
            if (gpioPWM(PWM_PIN, duty) != 0) {
                fprintf(stderr, "Error: gpioPWM failed on GPIO %d.\n", PWM_PIN);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("GPIO %d: PWM duty cycle = %d\n", PWM_PIN, duty);
            fflush(stdout);
            sleep(1);
        }
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

