        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value (trigger high)");
            goto cleanup;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value (trigger low)");
            goto cleanup;
        }

        long long t0 = now_us();
        while (gpiod_line_get_value(echo) == 0) {
            if (!running) goto cleanup;
            if (now_us() - t0 > 100000) {
                fprintf(stderr, "Timeout waiting for echo start\n");
                goto cleanup;
            }
        }
        long long t_rise = now_us();

        while (gpiod_line_get_value(echo) == 1) {
            if (!running) goto cleanup;
            if (now_us() - t_rise > 100000) {
                fprintf(stderr, "Timeout waiting for echo end\n");
                goto cleanup;
            }
        }
        long long t_fall = now_us();

        long long pulse_us = t_fall - t_rise;
        double distance_cm = (double)pulse_us * 0.0343 / 2.0;

        if (distance_cm < 2.0 || distance_cm > 400.0) {
            fprintf(stderr, "Out-of-range reading: %.2f cm\n", distance_cm);
        } else {
            printf("Distance: %.2f cm\n", distance_cm);
        }

        usleep(200000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_17 17
#define GPIO_18 18
#define GPIO_22 22
#define GPIO_23 23

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, sig_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pins[] = {GPIO_17, GPIO_18, GPIO_22, GPIO_23};
    int num_pins = sizeof(pins) / sizeof(pins[0]);

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        for (int i = 0; i < num_pins; i++) {
            int value = gpioRead(pins[i]);
            if (value < 0) {
                fprintf(stderr, "Failed to read GPIO %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("GPIO %d: %d\n", pins[i], value);
        }
        printf("\n");
        gpioDelay(100000); /* 0.1 seconds */
    }

    for (int i = 0; i < num_pins; i++) {
        gpioWrite(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <paho-mqtt-c/mqtt.h>
#include <paho-mqtt-c/Clients.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_CLIENT_ID "rpi_sensor_1"
#define MQTT_TOPIC "sensor/data"
#define MQTT_QOS 1
#define MQTT_TIMEOUT_MS 10000
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 1000
#define MAX_PAYLOAD_SIZE 256

static volatile sig_atomic_t running = 1;
static MQTTClient mqtt_client;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int validate_reading(const char *reading) {
    if (reading == NULL || strlen(reading) == 0) {
        fprintf(stderr, "Error: Reading is empty or null.\n");
        return 0;
    }
    return 1;
}

static int publish_reading(const char *reading) {
    if (!validate_reading(reading)) {
        return -1;
    }

    MQTTClient_message mqtt_message = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token = 0;

    mqtt_message.payload = (void *)reading;
    mqtt_message.payloadlen = (int)strlen(reading);
    mqtt_message.qos = MQTT_QOS;
    mqtt_message.retained = 0;

    int rc = MQTTClient_publishMessage(mqtt_client, MQTT_TOPIC, &mqtt_message, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: MQTT publish failed with return code %d.\n", rc);
        return -1;
    }

    int delivery_token = 0;
    rc = MQTTClient_waitForCompletion(mqtt_client, token, MQTT_TIMEOUT_MS);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: MQTT message delivery failed with return code %d.\n", rc);
        return -1;
    }

    printf("Reading '%s' published to topic '%s'.\n", reading, MQTT_TOPIC);
    return 0;
}

static int connect_to_mqtt_broker() {
    int rc = MQTTClient_connect(mqtt_client, MQTT_TIMEOUT_MS);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: Failed to connect to MQTT broker, return code %d.\n", rc);
        return -1;
    }
    return 0;
}

static void disconnect_from_mqtt_broker() {
    int rc = MQTTClient_disconnect(mqtt_client, MQTT_TIMEOUT_MS);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Warning: Failed to disconnect from MQTT broker, return code %d.\n", rc);
    }
}

static void cleanup() {
    disconnect_from_mqtt_broker();
    MQTTClient_destroy(&mqtt_client);
}

int main() {
    int rc;
    char timestamp[32];
    char reading[MAX_PAYLOAD_SIZE];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    MQTTClient_create(&mqtt_client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    MQTTClient_setCallbacks(mqtt_client, NULL, NULL, NULL, NULL);

    if (connect_to_mqtt_broker() != 0) {
        cleanup();
        return 1;
    }

    if (get_timestamp(timestamp, sizeof(timestamp)) != 0) {
        fprintf(stderr, "Error: Failed to get timestamp.\n");
        cleanup();
        return 1;
    }

    snprintf(reading, sizeof(reading), "{\"timestamp\": \"%s\", \"sensor\": \"rpi_sensor_1\", \"value\": 42}", timestamp);

    if (publish_reading(reading) != 0) {
        fprintf(stderr, "Error: Failed to publish reading.\n");
        cleanup();
        return 1;
    }

    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/ads1115"
#define ADS1115_ADDR 0x48
#define ADS1115_CONV_REG 0x00
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define ADS1115_CONFIG (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0_GND | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE)
#define ADS1115_CONV_REG 0x00
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_ADDR 0x48
#define I2C_BUS 1
#define NUM_READINGS 10

static volatile sig_atomic_t running = 1;
static struct mosquitto *mosq = NULL;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int16_t read_ads1115(int handle) {
    char config[3];
    config[0] = ADS1115_CONFIG_REG;
    config[1] = (ADS1115_CONFIG >> 8) & 0xFF;
    config[2] = ADS1115_CONFIG & 0xFF;
    if (i2cWriteDevice(handle, config, 3) < 0) {
        fprintf(stderr, "Error writing config to ADS1115\n");
        return -1;
    }
    gpioDelay(10000);
    char reg[1] = {ADS1115_CONV_REG};
    if (i2cWriteDevice(handle, reg, 1) < 0) {
        fprintf(stderr, "Error setting conversion register\n");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) < 0) {
        fprintf(stderr, "Error reading conversion data\n");
        return -1;
    }
    return (int16_t)((data[0] << 8) | data[1]);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60) != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker\n");
        mosquitto_destroy(mosq);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    for (int i = 0; i < NUM_READINGS && running; i++) {
        int16_t raw = read_ads1115(i2c_handle);
        if (raw < 0) {
            fprintf(stderr, "Error reading sensor, skipping\n");
            continue;
        }
        float voltage = (raw * 4.096) / 32768.0;
        char payload[64];
        snprintf(payload, sizeof(payload), "{\"sensor\":\"ads1115\",\"reading\":%.4f}", voltage);
        int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
        if (rc != MOSQ_ERR_SUCCESS) {
            fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(rc));
        }
        printf("Reading %d: %.4f V\n", i + 1, voltage);
        sleep(1);
    }
    if (running) {
        printf("Exiting after %d readings.\n", NUM_READINGS);
    }
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

