#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define MAX_TIMINGS 85

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint64_t now_us(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000000ULL + (uint64_t)ts.tv_nsec / 1000ULL;
}

static void sleep_us(uint64_t us) {
    struct timespec ts;
    ts.tv_sec = (time_t)(us / 1000000ULL);
    ts.tv_nsec = (long)((us % 1000000ULL) * 1000ULL);
    nanosleep(&ts, NULL);
}

static int read_dht22(struct gpiod_line *line, float *temperature, float *humidity) {
    uint8_t data[5] = {0, 0, 0, 0, 0};
    uint8_t last_state = 1;
    uint8_t counter = 0;
    uint8_t j = 0, i;

    *temperature = -999.0f;
    *humidity = -999.0f;

    if (gpiod_line_request_output(line, "dht22", 1) < 0) {
        fprintf(stderr, "Failed to request line as output\n");
        return -1;
    }
    gpiod_line_set_value(line, 1);
    sleep_us(500000);
    gpiod_line_set_value(line, 0);
    sleep_us(20000);
    gpiod_line_set_value(line, 1);
    sleep_us(40);

    if (gpiod_line_request_input(line, "dht22") < 0) {
        fprintf(stderr, "Failed to request line as input\n");
        return -1;
    }

    for (i = 0; i < MAX_TIMINGS && running; i++) {
        counter = 0;
        while (gpiod_line_get_value(line) == last_state && running) {
            counter++;
            sleep_us(1);
            if (counter == 255) break;
        }
        last_state = gpiod_line_get_value(line);

        if (!running) break;

        if (i >= MAX_TIMINGS) break;

        if ((i >= 4) && (i % 2 == 0)) {
            data[j / 8] <<= 1;
            if (counter > 16)
                data[j / 8] |= 1;
            j++;
        }
    }

    if (j >= 40 && data[4] == ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        *humidity = (float)((data[0] << 8) + data[1]) / 10.0f;
        *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0f;
        if (data[2] & 0x80) *temperature = -*temperature;
        return 0;
    }
    return -1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float temperature, humidity;
    int ret;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = read_dht22(line, &temperature, &humidity);
    if (ret == 0) {
        printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
    } else {
        fprintf(stderr, "Failed to read DHT22 sensor\n");
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return (ret == 0) ? EXIT_SUCCESS : EXIT_FAILURE;
}

