#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define CONSUMER    "hcsr04"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line(trigger)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(trigger)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    while (running) {
        /* Ensure trigger is low */
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig, 0)");
            goto cleanup;
        }
        usleep(2);

        /* 10 us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value(trig, 1)");
            goto cleanup;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig, 0)");
            goto cleanup;
        }

        /* Wait for echo rising edge (timeout ~500 ms) */
        int val;
        int waited = 0;
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value(echo)");
                goto cleanup;
            }
            if (val == 1) break;
            usleep(100);
            waited += 100;
        } while (waited < 500000 && running);

        if (!running) break;
        if (val != 1) {
            fprintf(stderr, "Error: Echo pin did not go high (device absent or no object)\n");
            goto cleanup;
        }

        /* Measure echo pulse width (timeout ~500 ms) */
        int high_us = 0;
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value(echo)");
                goto cleanup;
            }
            if (val == 0) break;
            usleep(1);
            high_us++;
        } while (high_us < 500000 && running);

        if (!running) break;
        if (val != 0) {
            fprintf(stderr, "Error: Echo pin did not go low (timeout)\n");
            goto cleanup;
        }

        /* Speed of sound ~343 m/s => distance = (high_us * 0.0343) / 2 */
        float distance = (high_us * 0.0343f) / 2.0f;
        printf("Distance: %.2f cm\n", distance);
        fflush(stdout);

        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

