        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", pins[i]);
            goto cleanup;
        }
        ret = gpiod_line_request_output(lines[i], "output_check", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request output on GPIO %d\n", pins[i]);
            goto cleanup;
        }
    }

    for (i = 0; i < NUM_GPIOS; i++) {
        values[i] = gpiod_line_get_value(lines[i]);
        if (values[i] < 0) {
            fprintf(stderr, "Failed to read GPIO %d\n", pins[i]);
