        }
    }

    for (i = 0; i < NUM_GPIOS; i++) {
        printf("GPIO %d: %d\n", pins[i], values[i]);
    }
    fflush(stdout);

    for (int cycle = 0; cycle < NUM_CYCLES && running; cycle++) {
        for (i = 0; i < NUM_GPIOS; i++) {
            values[i] = gpiod_line_get_value(lines[i]);
            if (values[i] < 0) {
                fprintf(stderr, "Failed to read GPIO %d\n", pins[i]);
                goto cleanup;
            }
        }
        for (i = 0; i < NUM_GPIOS; i++) {
            printf("GPIO %d: %d\n", pins[i], values[i]);
        }
        fflush(stdout);
        sleep(CYCLE_SECONDS);
    }

cleanup:
    for (i = 0; i < NUM_GPIOS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return (running == 0) ? EXIT_SUCCESS : EXIT_FAILURE;
}

