#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SHT31_ADDR 0x44
#define I2C_BUS "/dev/i2c-1"
#define MEASURE_CMD_MSB 0x2C
#define MEASURE_CMD_LSB 0x06
#define MEASUREMENT_DELAY_MS 10
#define SLEEP_INTERVAL_S 5

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t msb, uint8_t lsb) {
    uint8_t buf[2] = {msb, lsb};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int sht31_read(int fd, float *temp, float *hum) {
    uint8_t data[6];

    if (i2c_write_cmd(fd, MEASURE_CMD_MSB, MEASURE_CMD_LSB) < 0)
        return -1;

    usleep(MEASUREMENT_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, data, 6) < 0)
        return -1;

    uint16_t st = (data[0] << 8) | data[1];
    uint16_t srh = (data[3] << 8) | data[4];

    if (st == 0 || srh == 0) {
        fprintf(stderr, "SHT31: invalid sensor data (st=0x%04X, srh=0x%04X)\n", st, srh);
        return -1;
    }

    *temp = -45.0f + 175.0f * (float)st / 65535.0f;
    *hum = 100.0f * (float)srh / 65535.0f;

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SHT31_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SHT31_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    while (running) {
        float temp, hum;
        if (sht31_read(fd, &temp, &hum) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read SHT31 sensor\n");
        }
        sleep(SLEEP_INTERVAL_S);
    }

    close(fd);
    return 0;
}

