#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_PINS 3
#define CONSUMER "output_control"

static const unsigned int pins[NUM_PINS] = {2, 3, 17};
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_PINS];
static volatile sig_atomic_t keep_running = 1;

static void cleanup(void) {
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request output on line %u\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    for (int cycle = 1; cycle <= 3 && keep_running; cycle++) {
        for (int i = 0; i < NUM_PINS; i++) {
            int val = (cycle + i) % 2;
            if (gpiod_line_set_value(lines[i], val) < 0) {
                fprintf(stderr, "Failed to set value on line %u\n", pins[i]);
                cleanup();
                return EXIT_FAILURE;
            }
            printf("Cycle %d: GPIO %u set to %d\n", cycle, pins[i], val);
        }
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 2

static struct gpiod_line *line = NULL;
static struct gpiod_chip *chip = NULL;

static void cleanup_and_exit(int signum) {
    (void)signum;
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main(void) {
    int ret;
    int val;

    /* Open GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    /* Request output, initial value 0 */
    ret = gpiod_line_request_output(line, "output_test", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    /* Read and report current value */
    val = gpiod_line_get_value(line);
    if (val < 0) {
        perror("gpiod_line_get_value");
        cleanup_and_exit(0);
    }
    printf("Current value: %d\n", val);

    /* Set value to 1 */
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        cleanup_and_exit(0);
    }

    /* Read and report new value */
    val = gpiod_line_get_value(line);
    if (val < 0) {
        perror("gpiod_line_get_value");
        cleanup_and_exit(0);
    }
    printf("New value: %d\n", val);

    /* Set up signal handler for clean exit */
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    /* Keep the program alive until a signal is received */
    while (1) {
        sleep(1);
    }

    return 0;
}

