#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 23
#define CONSUMER "output_control"

static volatile sig_atomic_t keep_running = 1;

static void int_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value 0 */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop: toggle the line every 0.5 seconds */
    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        val = val ? 0 : 1;
        ret = gpiod_line_set_value(line, val);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE, val);
        fflush(stdout);

        /* Sleep 0.5 seconds, checking keep_running every 100 ms */
        for (int i = 0; i < 5 && keep_running; i++) {
            usleep(100000);
        }
    }

    /* Clean up: release the line and close the chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

