#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define W1_GPIO 4
#define W1_DEVICES_PATH "/sys/bus/w1/devices/"
#define W1_SLAVE_PATH "/sys/bus/w1/devices/w1_slave"
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(const char *device_path, float *temperature) {
    FILE *fp;
    char line[256];
    char path[256];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        snprintf(path, sizeof(path), "%s/w1_slave", device_path);

        fp = fopen(path, "r");
        if (fp == NULL) {
            fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
            retries++;
            sleep(1);
            continue;
        }

        if (fgets(line, sizeof(line), fp) == NULL) {
            fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
            fclose(fp);
            retries++;
            sleep(1);
            continue;
        }
        fclose(fp);

        if (strstr(line, "YES") == NULL) {
            fprintf(stderr, "Sensor not ready: %s\n", line);
            retries++;
            sleep(1);
            continue;
        }

        char *temp_str = strstr(line, "t=");
        if (temp_str == NULL) {
            fprintf(stderr, "Temperature data not found in: %s\n", line);
            retries++;
            sleep(1);
            continue;
        }

        long temp_milli = strtol(temp_str + 2, NULL, 10);
        *temperature = (float)temp_milli / 1000.0;
        return 0;
    }

    fprintf(stderr, "Failed to read temperature after %d retries.\n", MAX_RETRIES);
    return -1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return 1;
    }

    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    printf("Starting DS18B20 temperature readings on GPIO %d...\n", W1_GPIO);

    for (int i = 0; i < 3 && running; i++) {
        float temperature;
        if (read_temperature(W1_SLAVE_PATH, &temperature) == 0) {
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature after %d attempts.\n", MAX_RETRIES);
            return 1;
        }

        if (i < 2 && running) {
            sleep(5);
        }
    }

    printf("Exiting.\n");
    return 0;
}

