#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN    23
#define SENSOR_PIN  24

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MAX_DISTANCE_CM 400.0
#define ECHO_TIMEOUT_US 30000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static void sleep_us(long long us) {
    struct timespec ts;
    ts.tv_sec  = us / 1000000LL;
    ts.tv_nsec = (us % 1000000LL) * 1000LL;
    nanosleep(&ts, NULL);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        perror("gpiod_line_request_output (trig)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input (echo)");
        goto cleanup;
    }

    while (running) {
        /* Ensure trigger is low */
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value (trig low)");
            goto cleanup;
        }
        sleep_us(5);

        /* 10 us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value (trig high)");
            goto cleanup;
        }
        sleep_us(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value (trig low)");
            goto cleanup;
        }

        /* Wait for echo rising edge (timeout 30 ms) */
        long long start = now_us();
        int val;
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value (echo)");
                goto cleanup;
            }
            if (now_us() - start > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for echo start\n");
                goto cleanup;
            }
        } while (val == 0);

        long long echo_start = now_us();

        /* Wait for echo falling edge (timeout 30 ms) */
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value (echo)");
                goto cleanup;
            }
            if (now_us() - echo_start > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for echo end\n");
                goto cleanup;
            }
        } while (val == 1);

        long long echo_end = now_us();
        long long pulse_us = echo_end - echo_start;

        double distance = (double)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0;

        if (distance < 0.0 || distance > MAX_DISTANCE_CM) {
            fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        } else {
            printf("Distance: %.2f cm\n", distance);
        }

        sleep_us(100000); /* 0.1 s */
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define CYCLES 10

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "gpio17_cycle", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < CYCLES && running; i++) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value high");
            break;
        }
        printf("Cycle %d: GPIO %d HIGH\n", i + 1, GPIO_LINE);
        fflush(stdout);
        sleep(1);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value low");
            break;
        }
        printf("Cycle %d: GPIO %d LOW\n", i + 1, GPIO_LINE);
        fflush(stdout);
        sleep(1);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    if (!running) {
        fprintf(stderr, "\nInterrupted by signal. Exiting gracefully.\n");
    }

    return EXIT_SUCCESS;
}

