#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 4
#define PWM_PIN_2 17
#define PWM_PIN_3 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define VALID_THRESHOLD 0.0
#define INVALID_THRESHOLD 1.0
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", PWM_PIN_1);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", PWM_PIN_2);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", PWM_PIN_3);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", PWM_PIN_1);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", PWM_PIN_2);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", PWM_PIN_3);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", PWM_PIN_1);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", PWM_PIN_2);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", PWM_PIN_3);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    while (running) {
        float reading = 0.5f;
        if (reading < VALID_THRESHOLD || reading > INVALID_THRESHOLD) {
            fprintf(stderr, "Error: invalid reading: %.2f\n", reading);
            cleanup_gpio();
            return EXIT_FAILURE;
        }

        int duty_cycle = (int)(reading * PWM_RANGE);
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

        if (gpioPWM(PWM_PIN_1, duty_cycle) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d\n", PWM_PIN_1);
            cleanup_gpio();
            return EXIT_FAILURE;
        }
        if (gpioPWM(PWM_PIN_2, duty_cycle) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d\n", PWM_PIN_2);
            cleanup_gpio();
            return EXIT_FAILURE;
        }
        if (gpioPWM(PWM_PIN_3, duty_cycle) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d\n", PWM_PIN_3);
            cleanup_gpio();
            return EXIT_FAILURE;
        }

        printf("PWM Duty Cycle: %d\n", duty_cycle);
        fflush(stdout);

        usleep(LOOP_DELAY_US);
    }

    cleanup_gpio();
    return EXIT_SUCCESS;
}

