#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define MAX_CYCLES 3
#define TIMEOUT_US 100000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint64_t now_us(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000000ULL + (uint64_t)ts.tv_nsec / 1000ULL;
}

static void delay_us(uint64_t us) {
    uint64_t start = now_us();
    while (now_us() - start < us) {
        if (!running) break;
    }
}

static int wait_level(struct gpiod_line *line, int level, uint64_t timeout_us) {
    uint64_t start = now_us();
    while (gpiod_line_get_value(line) != level) {
        if (!running) return -1;
        if (now_us() - start > timeout_us) return -1;
    }
    return 0;
}

static int read_dht22(struct gpiod_line *line, float *temperature, float *humidity) {
    uint8_t data[5] = {0};
    int i;

    if (gpiod_line_request_output(line, "dht22", 1) < 0) {
        fprintf(stderr, "Failed to request line as output\n");
        return -1;
    }
    gpiod_line_set_value(line, 1);
    delay_us(500000);
    gpiod_line_set_value(line, 0);
    delay_us(20000);
    gpiod_line_set_value(line, 1);
    delay_us(40);

    if (gpiod_line_request_input(line, "dht22") < 0) {
        fprintf(stderr, "Failed to request line as input\n");
        return -1;
    }

    if (wait_level(line, 0, TIMEOUT_US) < 0) return -1;
    if (wait_level(line, 1, TIMEOUT_US) < 0) return -1;
    if (wait_level(line, 0, TIMEOUT_US) < 0) return -1;

    for (i = 0; i < 40; i++) {
        if (wait_level(line, 1, TIMEOUT_US) < 0) return -1;
        uint64_t start = now_us();
        if (wait_level(line, 0, TIMEOUT_US) < 0) return -1;
        uint64_t pulse = now_us() - start;
        data[i / 8] <<= 1;
        if (pulse > 50) data[i / 8] |= 1;
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "Checksum error\n");
        return -1;
    }

    *humidity = (float)((data[0] << 8) | data[1]) / 10.0f;
    *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
    if (data[2] & 0x80) *temperature = -*temperature;

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature, humidity;
    int cycles = 0;

    while (running && cycles < MAX_CYCLES) {
        if (read_dht22(line, &temperature, &humidity) == 0) {
            printf("Cycle %d: Temperature = %.1f C, Humidity = %.1f %%\n",
                   cycles + 1, temperature, humidity);
            cycles++;
        } else {
            fprintf(stderr, "Failed to read DHT22 data\n");
        }
        if (running) sleep(2);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

