#define GPIO_4   4
#define GPIO_17  17
#define GPIO_18  18
#define NUM_PINS 3
#define CYCLES   5
#define DELAY_MS 50

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    const unsigned int pins[NUM_PINS] = {GPIO_4, GPIO_17, GPIO_18};
    int vals[NUM_PINS] = {0, 0, 0};
    int i;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "output-cycle", 0) < 0) {
            fprintf(stderr, "Failed to request line %u as output\n", pins[i]);
            goto cleanup;
        }
    }

    for (i = 0; i < NUM_PINS; i++) {
        vals[i] = 1;
        if (gpiod_line_set_value(lines[i], vals[i]) < 0) {
            fprintf(stderr, "Failed to set line %u high\n", pins[i]);
            goto cleanup;
        }
    }

    for (i = 0; i < CYCLES && running; i++) {
        printf("Cycle %d: GPIO 4=%d, GPIO 17=%d, GPIO 18=%d\n",
               i + 1, vals[0], vals[1], vals[2]);
        fflush(stdout);
        usleep(DELAY_MS * 1000);
