            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) gpiod_chip_close(chip);
    return (running == 0) ? EXIT_SUCCESS : EXIT_FAILURE;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 27
#define PWM_RANGE 1000
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duty_cycle = 500;
    if (gpioPWM(PWM_PIN_1, duty_cycle) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(PWM_PIN_2, duty_cycle) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", PWM_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM on GPIO %d and GPIO %d set to %d/1000\n", PWM_PIN_1, PWM_PIN_2, duty_cycle);

    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioTerminate();
    printf("\nPWM stopped and pigpio terminated.\n");
    return EXIT_SUCCESS;
}

