#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 4
#define PWM_PIN_2 17
#define PWM_PIN_3 18
#define PWM_PIN_4 27

#define PWM_RANGE 1000
#define PWM_FREQ 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    for (int i = 0; i < 4; i++) {
        gpioSetMode(pins[i], PI_OUTPUT);
        gpioSetPWMrange(pins[i], PWM_RANGE);
        gpioSetPWMfrequency(pins[i], PWM_FREQ);
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int states[] = {0, 500, 250, 750};
    int num_states = sizeof(states) / sizeof(states[0]);

    for (int cycle = 0; cycle < 5 && !terminate; cycle++) {
        for (int i = 0; i < 4; i++) {
            gpioPWM(pins[i], states[i % num_states]);
        }
        printf("Cycle %d: %d %d %d %d\n", cycle + 1,
               states[0], states[1], states[2], states[3]);
        fflush(stdout);
        sleep(60);
    }

    for (int i = 0; i < 4; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return 0;
}

