#include <pigpio.h>

#define GPIO_17 17
#define GPIO_18 18
#define GPIO_27 27
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define DELAY_US 1000000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_17, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_18, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_27, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(GPIO_17, PWM_RANGE) < 0 ||
        gpioSetPWMrange(GPIO_18, PWM_RANGE) < 0 ||
        gpioSetPWMrange(GPIO_27, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(GPIO_17, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GPIO_18, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GPIO_27, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int s1 = gpioPWM(GPIO_17, 500);
        int s2 = gpioPWM(GPIO_18, 500);
        int s3 = gpioPWM(GPIO_27, 500);

        if (s1 < 0 || s2 < 0 || s3 < 0) {
            fprintf(stderr, "PWM write failed (s1=%d s2=%d s3=%d)\n", s1, s2, s3);
            break;
        }

        printf("GPIO 17: %d, GPIO 18: %d, GPIO 27: %d\n", 500, 500, 500);
        fflush(stdout);

        gpioDelay(DELAY_US);
    }

    gpioPWM(GPIO_17, 0);
    gpioPWM(GPIO_18, 0);
    gpioPWM(GPIO_27, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

