#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define TRIG_PIN 4
#define ECHO_PIN 17
#define LED_PIN 18
#define BUZZER_PIN 27

#define CHIP_NAME "gpiochip0"
#define CONSUMER "hc-sr04"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *led = NULL, *buzzer = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIG_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    led = gpiod_chip_get_line(chip, LED_PIN);
    buzzer = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!trig || !echo || !led || !buzzer) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, CONSUMER, 0) < 0 ||
        gpiod_line_request_input(echo, CONSUMER) < 0 ||
        gpiod_line_request_output(led, CONSUMER, 0) < 0 ||
        gpiod_line_request_output(buzzer, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set TRIG low: %s\n", strerror(errno));
        goto cleanup;
    }
    usleep(1000);

    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Failed to set TRIG high: %s\n", strerror(errno));
        goto cleanup;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set TRIG low: %s\n", strerror(errno));
        goto cleanup;
    }

    int timeout = 0;
    while (gpiod_line_get_value(echo) == 0) {
        if (++timeout > 100000) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            goto cleanup;
        }
        usleep(1);
    }

    struct timeval start, end;
    if (gettimeofday(&start, NULL) < 0) {
        fprintf(stderr, "gettimeofday failed: %s\n", strerror(errno));
        goto cleanup;
    }

    timeout = 0;
    while (gpiod_line_get_value(echo) == 1) {
        if (++timeout > 100000) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            goto cleanup;
        }
        usleep(1);
    }

    if (gettimeofday(&end, NULL) < 0) {
        fprintf(stderr, "gettimeofday failed: %s\n", strerror(errno));
        goto cleanup;
    }

    double elapsed = (end.tv_sec - start.tv_sec) + (end.tv_usec - start.tv_usec) / 1000000.0;
    double distance = (elapsed * 34300.0) / 2.0;

    printf("Distance: %.2f cm\n", distance);

    if (gpiod_line_set_value(led, 1) < 0 || gpiod_line_set_value(buzzer, 1) < 0) {
        fprintf(stderr, "Failed to set outputs: %s\n", strerror(errno));
        goto cleanup;
    }
    usleep(500000);
    if (gpiod_line_set_value(led, 0) < 0 || gpiod_line_set_value(buzzer, 0) < 0) {
        fprintf(stderr, "Failed to clear outputs: %s\n", strerror(errno));
        goto cleanup;
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (led) gpiod_line_release(led);
    if (buzzer) gpiod_line_release(buzzer);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

