#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define BMP280_I2C_ADDR 0x03
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_ID 0xD0
#define BMP280_REG_CALIB 0x88
#define BMP280_RESET_CMD 0xB6
#define BMP280_CHIP_ID 0x58

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int bmp280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, BMP280_REG_ID, &id) < 0) {
        fprintf(stderr, "Error reading chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Invalid chip ID: 0x%02X (expected 0x%02X)\n", id, BMP280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg8(fd, BMP280_REG_RESET, BMP280_RESET_CMD) < 0) {
        fprintf(stderr, "Error resetting sensor: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);

    uint8_t calib[24];
    if (i2c_read_burst(fd, BMP280_REG_CALIB, calib, sizeof(calib)) < 0) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        return -1;
    }

    uint16_t dig_T1 = (calib[1] << 8) | calib[0];
    int16_t dig_T2 = (calib[3] << 8) | calib[2];
    int16_t dig_T3 = (calib[5] << 8) | calib[4];
    uint16_t dig_P1 = (calib[7] << 8) | calib[6];
    int16_t dig_P2 = (calib[9] << 8) | calib[8];
    int16_t dig_P3 = (calib[11] << 8) | calib[10];
    int16_t dig_P4 = (calib[13] << 8) | calib[12];
    int16_t dig_P5 = (calib[15] << 8) | calib[14];
    int16_t dig_P6 = (calib[17] << 8) | calib[16];
    int16_t dig_P7 = (calib[19] << 8) | calib[18];
    int16_t dig_P8 = (calib[21] << 8) | calib[20];
    int16_t dig_P9 = (calib[23] << 8) | calib[22];

    (void)dig_T1; (void)dig_T2; (void)dig_T3;
    (void)dig_P1; (void)dig_P2; (void)dig_P3; (void)dig_P4;
    (void)dig_P5; (void)dig_P6; (void)dig_P7; (void)dig_P8; (void)dig_P9;

    if (i2c_write_reg8(fd, BMP280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error writing ctrl_meas register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bmp280_read(int fd, float *temp, float *press) {
    uint8_t data[6];
    if (i2c_read_burst(fd, BMP280_REG_PRESS_MSB, data, 6) < 0) {
        fprintf(stderr, "Error reading data registers: %s\n", strerror(errno));
        return -1;
    }

    int32_t raw_p = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t raw_t = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

    (void)raw_p; (void)raw_t;
    *temp = 0.0f;
    *press = 0.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", BMP280_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (bmp280_init(fd) < 0) {
        fprintf(stderr, "BMP280 initialization failed.\n");
        close(fd);
        return 1;
    }

    for (int i = 0; i < 3 && running; i++) {
        float temp, press;
        if (bmp280_read(fd, &temp, &press) == 0) {
            printf("Reading %d: Temperature = %.2f C, Pressure = %.2f Pa\n", i + 1, temp, press);
        } else {
            fprintf(stderr, "Error reading BMP280 data.\n");
            close(fd);
            return 1;
        }
        sleep(1);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
