static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "output-control", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    int val = gpiod_line_get_value(line);
    if (val < 0) {
        perror("gpiod_line_get_value");
        goto cleanup;
    }

    printf("GPIO %d value: %d\n", GPIO_LINE, val);
    fflush(stdout);

    ret = EXIT_SUCCESS;

cleanup:
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "output-control", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Failed to read line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("GPIO %d value: %d\n", GPIO_LINE_OFFSET, value);
    fflush(stdout);

    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define BME280_I2C_ADDR 0x76
#define BME280_REG_ID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_STATUS 0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_DATA 0xF7
#define BME280_REG_CALIB_00 0x88
#define BME280_REG_CALIB_26 0xE1

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int bme280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg(fd, BME280_REG_ID, &id, 1) < 0) {
        fprintf(stderr, "Error reading chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != 0x60) {
        fprintf(stderr, "Unexpected chip ID: 0x%02x (expected 0x60)\n", id);
        return -1;
    }

    if (i2c_write_reg(fd, BME280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error resetting chip: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);

    uint8_t status;
    for (int i = 0; i < 10; i++) {
        if (i2c_read_reg(fd, BME280_REG_STATUS, &status, 1) < 0) {
            fprintf(stderr, "Error reading status: %s\n", strerror(errno));
            return -1;
        }
        if ((status & 0x01) == 0) break;
        usleep(2000);
    }
    if ((status & 0x01) != 0) {
        fprintf(stderr, "Sensor still busy after reset\n");
        return -1;
    }

    if (i2c_write_reg(fd, BME280_REG_CTRL_HUM, 0x01) < 0) return -1;
    if (i2c_write_reg(fd, BME280_REG_CONFIG, 0xA0) < 0) return -1;
    if (i2c_write_reg(fd, BME280_REG_CTRL_MEAS, 0x27) < 0) return -1;

    return 0;
}

static int bme280_read(int fd, float *temp, float *hum, float *press) {
    uint8_t data[8];
    if (i2c_read_reg(fd, BME280_REG_DATA, data, 8) < 0) return -1;

    uint32_t raw_p = ((uint32_t)data[0] << 12) | ((uint32_t)data[1] << 4) | ((uint32_t)data[2] >> 4);
    uint32_t raw_t = ((uint32_t)data[3] << 12) | ((uint32_t)data[4] << 4) | ((uint32_t)data[5] >> 4);
    uint32_t raw_h = ((uint32_t)data[6] << 8) | (uint32_t)data[7];

    uint8_t calib[26];
    if (i2c_read_reg(fd, BME280_REG_CALIB_00, calib, 26) < 0) return -1;
    if (i2c_read_reg(fd, BME280_REG_CALIB_26, calib + 26, 7) < 0) return -1;

    uint16_t dig_T1 = (calib[1] << 8) | calib[0];
    int16_t dig_T2 = (calib[3] << 8) | calib[2];
    int16_t dig_T3 = (calib[5] << 8) | calib[4];
    uint16_t dig_P1 = (calib[7] << 8) | calib[6];
    int16_t dig_P2 = (calib[9] << 8) | calib[8];
    int16_t dig_P3 = (calib[11] << 8) | calib[10];
    int16_t dig_P4 = (calib[13] << 8) | calib[12];
    int16_t dig_P5 = (calib[15] << 8) | calib[14];
    int16_t dig_P6 = (calib[17] << 8) | calib[16];
    int16_t dig_P7 = (calib[19] << 8) | calib[18];
    int16_t dig_P8 = (calib[21] << 8) | calib[20];
    int16_t dig_P9 = (calib[23] << 8) | calib[22];
    uint8_t dig_H1 = calib[25];
    int16_t dig_H2 = (calib[27] << 8) | calib[26];
    uint8_t dig_H3 = calib[28];
    int16_t dig_H4 = (calib[29] << 4) | (calib[30] & 0x0F);
    int16_t dig_H5 = (calib[31] << 4) | (calib[30] >> 4);
    int8_t dig_H6 = (int8_t)calib[32];

    double var1 = ((double)raw_t / 16384.0 - (double)dig_T1 / 1024.0) * (double)dig_T2;
    double var2 = ((double)raw_t / 131072.0 - (double)dig_T1 / 8192.0) * ((double)raw_t / 131072.0 - (double)dig_T1 / 8192.0) * (double)dig_T3;
    double t_fine = var1 + var2;
    *temp = (float)(t_fine / 5120.0);

    double p_var1 = (t_fine / 2.0) - 64000.0;
    double p_var2 = p_var1 * p_var1 * (double)dig_P6 / 32768.0;
    p_var2 = p_var2 + p_var1 * (double)dig_P5 * 2.0;
    p_var2 = p_var2 / 4.0 + (double)dig_P4 * 65536.0;
    p_var1 = ((double)dig_P3 * p_var1 * p_var1 / 524288.0 + (double)dig_P2 * p_var1) / 524288.0;
    p_var1 = (1.0 + p_var1 / 32768.0) * (double)dig_P1;
    if (p_var1 == 0.0) { *press = 0.0; return 0; }
    double p = 1048576.0 - (double)raw_p;
    p = (p - p_var2 / 4096.0) * 6250.0 / p_var1;
    p_var1 = (double)dig_P9 * p * p / 2147483648.0;
    p_var2 = p * (double)dig_P8 / 32768.0;
    p = p + (p_var1 + p_var2 + (double)dig_P7) / 16.0;
    *press = (float)(p / 100.0);

    double h = t_fine - 76800.0;
    h = ((double)raw_h - ((double)dig_H4 * 64.0 + (double)dig_H5 / 16384.0 * h)) * ((double)dig_H2 / 65536.0 * (1.0 + (double)dig_H6 / 67108864.0 * h * (1.0 + (double)dig_H3 / 67108864.0 * h)));
    h = h * (1.0 - (double)dig_H1 * h / 524288.0);
    if (h > 100.0) h = 100.0;
    if (h < 0.0) h = 0.0;
    *hum = (float)h;

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C address 0x%02x: %s\n", BME280_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (bme280_init(fd) < 0) {
        fprintf(stderr, "BME280 initialization failed\n");
        close(fd);
        return 1;
    }

    for (int i = 0; i < 3 && running; i++) {
        float temp, hum, press;
        if (bme280_read(fd, &temp, &hum, &press) < 0) {
            fprintf(stderr, "Error reading BME280 data: %s\n", strerror(errno));
            close(fd);
            return 1;
        }
        printf("Reading %d: Temperature = %.2f C, Humidity = %.2f %%, Pressure = %.2f hPa\n", i + 1, temp, hum, press);
        sleep(5);
    }

    close(fd);
    return 0;
}

