#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define LED_PIN 27
#define CONSUMER "hc-sr04"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *led = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!trig || !echo || !led) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, CONSUMER, 0) < 0) {
        perror("request_output trigger");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        perror("request_input echo");
        goto cleanup;
    }
    if (gpiod_line_request_output(led, CONSUMER, 0) < 0) {
        perror("request_output led");
        goto cleanup;
    }

    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("set_value trigger low");
        goto cleanup;
    }
    usleep(1000);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("set_value trigger high");
        goto cleanup;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("set_value trigger low");
        goto cleanup;
    }

    /* Wait for echo rising edge (timeout 100 ms) */
    int val;
    int timeout = 0;
    while (running) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("get_value echo");
            goto cleanup;
        }
        if (val == 1) break;
        usleep(100);
        if (++timeout > 100) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            goto cleanup;
        }
    }
    if (!running) goto cleanup;

    struct timespec start, end;
    if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
        perror("clock_gettime start");
        goto cleanup;
    }

    /* Wait for echo falling edge (timeout 1 s) */
    timeout = 0;
    while (running) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("get_value echo");
            goto cleanup;
        }
        if (val == 0) break;
        usleep(100);
        if (++timeout > 1000) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            goto cleanup;
        }
    }
    if (!running) goto cleanup;

    if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
        perror("clock_gettime end");
        goto cleanup;
    }

    double elapsed = (end.tv_sec - start.tv_sec) +
                     (end.tv_nsec - start.tv_nsec) / 1e9;
    double distance = (elapsed * 34300.0) / 2.0;

    if (distance < 2.0 || distance > 400.0) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
    } else {
        printf("Distance: %.2f cm\n", distance);
    }

    if (gpiod_line_set_value(led, 1) < 0) {
        perror("set_value led high");
        goto cleanup;
    }
    usleep(500000);
    if (gpiod_line_set_value(led, 0) < 0) {
        perror("set_value led low");
        goto cleanup;
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (led) gpiod_line_release(led);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 18
#define PWM_PIN_2 21
#define PWM_PIN_3 22

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], 1000) < 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 128) != 0) {
            fprintf(stderr, "Failed to start PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("PWM output started on GPIO %d, GPIO %d, GPIO %d\n", PWM_PIN_1, PWM_PIN_2, PWM_PIN_3);
    fflush(stdout);

    while (running) {
        gpioDelay(100000);
    }

    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        gpioPWM(pins[i], 0);
    }

    gpioTerminate();
    printf("PWM output stopped\n");
    return EXIT_SUCCESS;
}

