#include <pigpio.h>

#define PWM_PIN_2  2
#define PWM_PIN_3  3
#define PWM_PIN_18 18
#define PWM_RANGE  1000
#define PWM_FREQ   1000
#define LOOP_DELAY 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device absent or permissions?).\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_18, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_18, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_18, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int duty = 500;
        if (gpioPWM(PWM_PIN_2, duty) != 0 ||
            gpioPWM(PWM_PIN_3, duty) != 0 ||
            gpioPWM(PWM_PIN_18, duty) != 0) {
            fprintf(stderr, "Error: gpioPWM failed.\n");
            break;
        }
        printf("PWM on GPIO %d, GPIO %d, GPIO %d: duty cycle = %d\n",
               PWM_PIN_2, PWM_PIN_3, PWM_PIN_18, duty);
        fflush(stdout);
        sleep(LOOP_DELAY);
    }

    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_18, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
