#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 2
#define GPIO_LINE_14 14

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static struct gpiod_line *line_14 = NULL;

void cleanup_and_exit(int signum) {
    (void)signum;
    if (line) {
        gpiod_line_release(line);
    }
    if (line_14) {
        gpiod_line_release(line_14);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main(void) {
    int ret;
    int val;

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request output, initial low
    ret = gpiod_line_request_output(line, "output_test", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Get GPIO line 14
    line_14 = gpiod_chip_get_line(chip, GPIO_LINE_14);
    if (!line_14) {
        perror("gpiod_chip_get_line 14");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request output, initial low
    ret = gpiod_line_request_output(line_14, "output_test_14", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output 14");
        gpiod_line_release(line);
        gpiod_line_release(line_14);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handler for clean exit
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    // Read and print the state of the line
    val = gpiod_line_get_value(line);
    if (val < 0) {
        perror("gpiod_line_get_value");
        cleanup_and_exit(0);
