#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define TRIGGER_PIN 18
#define ECHO_PIN    23
#define TIMEOUT_US  1000000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static long long elapsed_us(long long start) {
    return now_us() - start;
}

static int wait_for_level(struct gpiod_line *line, int target, long long timeout_us) {
    long long deadline = now_us() + timeout_us;
    int val;
    while (running) {
        val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error reading line: %s\n", strerror(errno));
            return -1;
        }
        if (val == target) return 0;
        if (now_us() >= deadline) return 1;
        usleep(10);
    }
    return 1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        fprintf(stderr, "Failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request trigger as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo as input: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Ensure trigger is low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        goto cleanup;
    }
    usleep(1000);

    /* Send 10us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
        goto cleanup;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Wait for echo rising edge (timeout 1 s) */
    if (wait_for_level(echo, 1, TIMEOUT_US) != 0) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        goto cleanup;
    }

    long long start = now_us();

    /* Wait for echo falling edge (timeout 1 s) */
    if (wait_for_level(echo, 0, TIMEOUT_US) != 0) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        goto cleanup;
    }

    long long end = now_us();
    long long duration = end - start;

    /* Distance = (duration * speed_of_sound) / 2 */
    double distance = (double)duration * 0.0343 / 2.0;

    printf("Distance: %.2f cm\n", distance);
    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

